def encrypt(s):
    result = []
    for char in s:
        if char.isalpha():
            if char.islower():
                base = ord('a')
            else:
                base = ord('A')
            shifted = (ord(char) - base + 4) % 26 + base
            result.append(chr(shifted))
        else:
            result.append(char)
    return ''.join(result)

