def is_simple_power(x, n):
    if n == 1:
        return x == 1
    if n == 0:
        return x == 1
    import math
    if x <= 0:
        return False
    log_x = math.log(x)
    log_n = math.n
    if log_n == 0:
        return False
    power = log_x / log_n
    if abs(power - round(power)) > 1e-10:
        return False
    return n ** int(round(power)) == x

