def is_bored(S):
    import re
    sentences = re.split(r'[.!?]', S)
    count = 0
    for sentence in sentences:
        stripped = sentence.strip()
        if stripped.startswith("I") or stripped.startswith("I "):
            # Need to ensure it's the word "I", not just a prefix
            # Check if the sentence starts with "I" followed by non-alphanumeric or end of string
            if re.match(r'^I(\s|$|[^a-zA-Z0-9])', stripped):
                count += 1
    return count

